// @ts-ignore Generated by napi during build.
import * as generated from '../native/index.js';

const native = generated as { encode(value: unknown): string; decode(input: string): unknown };

export type LeanValue = string | number | boolean | null | LeanValue[] | { [key: string]: LeanValue };

export class LeanParseError extends Error {
  public readonly line: number;
  public readonly content: string;

  constructor(lineIndex: number, content: string, message: string) {
    super(`Line ${lineIndex + 1}: ${message} → "${content}"`);
    this.line = lineIndex + 1;
    this.content = content;
    this.name = 'LeanParseError';
  }
}

export function encode(data: LeanValue): string { return native.encode(data); }

export function decode(lean: string): LeanValue {
  try { return native.decode(lean) as LeanValue; }
  catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    const prefix = 'LEAN_PARSE_ERROR\t';
    if (message.startsWith(prefix)) {
      const [line, content, detail] = JSON.parse(message.slice(prefix.length)) as [number, string, string];
      throw new LeanParseError(line - 1, content, detail);
    }
    throw error;
  }
}
